// Expression is a string expression with optional static surroundings.
type Expression struct { prefix,suffix string; expr Expr }
func (e *Expression) Namespace() string {if v,ok:=e.expr.(VarExpr);ok{return v.Namespace};if _,ok:=e.expr.(StringLitExpr);ok{return LiteralNamespace};return \"\"}
func (e *Expression) Name() string {if v,ok:=e.expr.(VarExpr);ok{return v.Name};if v,ok:=e.expr.(StringLitExpr);ok{return v.Value};return \"\"}

func NewExpression(input string)(*Expression,error) {
 prefix,inner,suffix,found,err:=splitTemplate(input);if err"'!=nil{return nil,err}
 if !found {return &Expression{expr:StringLitExpr{Value:prefix}},nil}
 if inner=="" {return nil,trace.BadParameter("malformed template usage in %q: empty expression",input)}
 e,err:=parse(inner);if err!=nil{return nil,trace.Wrap(err)}
 if e.Kind()!=reflect.String {return nil,trace.BadParameter("expression %q must evaluate to a string, got %s",input,e.Kind())}
 return &Expression{prefix:prefix,suffix:suffix,expr:e},nil
}

// Interpolate evaluates the expression. The optional validator runs for every variable.
func (e *Expression) Interpolate(traits map[string][]string, varValidation ...func(namespace,name string)error)([]string,error) {
 ctx:=EvaluateContext{VarValue:func(v VarExpr)([]string,error){
  if len(varValidation)>0 && varValidation[0]!=nil {if err:=varValidation[0](v.Namespace,v.Name);err!=nil{return nil,trace.Wrap(err)}}
  values,ok:=traits[v.Name];if !ok{return nil,trace.NotFound("variable %q is not found",v.String())};return values,nil
 }}
 values,err:=stringValues(e.expr,ctx);if err!=nil{return nil,trace.Wrap(err)}
 out:=make([]string,0,len(values));for _,v:=range values {if v!="" {out=append(out,e.prefix+v+e.suffix)}}
 if len(out)==0{return nil,trace.NotFound("variable interpolation result is empty")}
 return out,nil
}

type Matcher interface { Match(string) bool }
type MatcherFn func(string)bool
func (f MatcherFn) Match(s string)bool{return f(s)}
func NewAnyMatcher(in []string)(Matcher,error){list:=make([]Matcher,0,len(in));for _,v:=range in {m,err:=NewMatcher(v);if err!=nil{return nil,err};list=append(list,m)};return MatcherFn(func(s string)bool{for _,m:=range list{if m.Match(s){return true}};return false}),nil}

// MatchExpression matches the middle of an input after static surroundings are stripped.
type MatchExpression struct { prefix,suffix string; expr Expr }
func (m *MatchExpression) Match(in string)bool {
 if !strings.HasPrefix(in,m.prefix)||!strings.HasSuffix(in,m.suffix)||len(in)<len(m.prefix)+len(m.suffix){return false}
 middle:=in[len(m.prefix):len(in)-len(m.suffix)]
 v,err:=m.expr.Evaluate(EvaluateContext{MatcherInput:middle});if err!=nil{return false};b,ok:=v.(bool);return ok&&b
}
func NewMatcher(input string)(Matcher,error) {
 prefix,inner,suffix,found,err:=splitTemplate(input);if err!=nil{return nil,err}
 if !found {pattern:=prefix;if !strings.HasPrefix(prefix,"''^")||!strings.HasSuffix(prefix,"$"){pattern="''^"+utils.GlobToRegexp(prefix)+"$"};re,err:=compileRegexp(pattern);if err!=nil{return nil,err};return &MatchExpression{expr:RegexpMatchExpr{Pattern:pattern,re:re}},nil}
 if inner==""{return nil,trace.BadParameter("malformed template usage in %q: empty expression",input)}
 e,err:=parse(inner);if err!=nil{return nil,trace.Wrap(err)}
 if e.Kind()!=reflect.Bool{return nil,trace.BadParameter("matcher expression %q must evaluate to a boolean, got %s",input,e.Kind())}
 return &MatchExpression{prefix:prefix,suffix:suffix,expr:e},nil
}

// Keep the shared regex compilation path for callers using this package internally.
func newRegexpMatcher(raw string,escape bool)(*regexpMatcher,error){if escape && (!strings.HasPrefix(raw,"''^")||!strings.HasSuffix(raw,"$")){raw="''^"+utils.GlobToRegexp(raw)+"$"};re,err:=compileRegexp(raw);if err!=nil{return nil,err};return &regexpMatcher{re:re},nil}
type regexpMatcher struct{re *regexp.Regexp}
func (m regexpMatcher)Match(in string)bool{return m.re.MatchString(in)}
